  await tick(400);
  const warm645 = JSON.parse((await call(apiW645, '/api/deepamp/get_models?fn=tts', 'GET')).body);
  const warmRow645 = (warm645.models || []).filter(function (x) { return x.id === 'kitten-tts2'; })[0];
  ok('T-645 cold start, second half: the cold read warmed the catalog on its own way out, so the next get_models answers the family from the engine\'s task list',
    warmRow645 && warmRow645.clone_optional === true, { kitten: warmRow645 });
  ok('T-645 source: the warm is a background kick, not an await — the model list the panel waits for is never behind a 130-file read',
    (function () {
      const src645c = require('fs').readFileSync(LIB, 'utf8');
      return /if \(!specsCache \|\| !specsCache\.by_family\) fetchSpecCatalog\(\)\.catch/.test(src645c)
        && !/await fetchSpecCatalog\(\)[\s\S]{0,120}fetchModels\(params\.get\('fn'\)/.test(src645c);
    })(), { note: 'get_models answers first, reads the catalog on its way out' });
  CW645.bag.release();

  // A specs tree that is not there used to answer as an EMPTY CATALOG with no error anywhere, and an empty catalog
  // made every file on the store look rogue. Both halves are pinned here: the state is reported, and the claim is
  // withheld when there is nothing to compare against.
  const C319M = makeCtx({ fastTimers: true, audit: true, auditSpecsMissing: true });
  mod.apply(C319M.ctx);
  await tick(40);
  const api319M = C319M.bag.registered.find(function (x) { return x.path === '/api/deepamp'; }).handler;
  await call(api319M, '/api/deepamp/get_models?fn=tts', 'GET');
  const audMiss319 = JSON.parse((await call(api319M, '/api/deepamp/models_audit', 'GET')).body);
  const ttsMiss319 = (audMiss319.endpoints || [])[0] || {};
  ok('T-319: with no spec directory readable the audit says so out loud instead of answering a silent zero',
    audMiss319.ok === true && audMiss319.catalog_readable === false && audMiss319.catalog_files === 0
    && audMiss319.catalog_packages === 0 && audMiss319.specs_read_ok === false
    && /nothing was readable/.test(String(audMiss319.catalog_note))
    && (audMiss319.specs_tried || []).length === 2, audMiss319);
