  mod.apply(C319F.ctx);
  await tick(40);
  const api319F = C319F.bag.registered.find(function (x) { return x.path === '/api/deepamp'; }).handler;
  await call(api319F, '/api/deepamp/get_models?fn=tts', 'GET');
