  C403.bag.release();

  // T-641 transport fix (2026-10-25 08:4x Berlin), found by the FIRST LIVE READ of this verb and not by a test.
  // cpu1.test answered the census in 3 ms with Content-Length 85 915 and 403 rows; the plugin answered
  // "package-sizes answer was not readable JSON", because the body came back through shell stdout, which the
  // shell service caps at 64 000 bytes (the number recorded at capFetchPage's own 2026-10-07 measurement). That
  // is the T-252 bug, re-hit by new code that ignored a rule this plugin already has. These checks pin the
  // TRANSPORT, because every count above would also pass against a fixture that never had to cross a stdout cap:
  // a fixture body always parses, a live 86 KB body did not.
  const CAPDIR641 = `${SUITE_STORE}`;
  const CTRANS641 = makeCtx({ fastTimers: true, audit: true });
  mod.apply(CTRANS641.ctx);
  await tick(40);
  const apiTrans641 = CTRANS641.bag.registered.find(function (x) { return x.path === '/api/deepamp'; }).handler;
  await call(apiTrans641, '/api/deepamp/get_models?fn=tts', 'GET');
  const transAns641 = JSON.parse((await call(apiTrans641, '/api/deepamp/endpoint_library?fn=tts&id=primary', 'GET')).body);
  const censusReads641 = CTRANS641.bag.shellCalls.filter(function (c) { return /package-sizes/.test(String(c)); }).map(String);
  const censusCmd641 = censusReads641[0] || '';
  const censusSpec641 = CTRANS641.bag.specs.filter(function (s) { return /package-sizes/.test(String(s.command)); })[0];
  const oCut641 = censusCmd641.indexOf(" -o '");
  const tmpCensus641 = oCut641 >= 0 ? censusCmd641.slice(oCut641 + 5, censusCmd641.indexOf("' -w '", oCut641)) : '';
  const rmsCensus641 = function (bag) { return bag.shellCalls.filter(function (c) { return /^rm -f '/.test(String(c)); }).map(String); };
  ok('T-641 transport: the census body never crosses stdout - one read, curl -o <temp> under the plugin dir with --max-filesize, and stdout carries only the -w triple (no -w \n%{http_code} body-on-stdout shape anywhere in this read)',
    censusReads641.length === 1 && oCut641 > 0 && tmpCensus641.indexOf(CAPDIR641 + '/cap_page_') === 0
    && censusCmd641.indexOf(' --max-filesize ') > 0
    && censusCmd641.indexOf("-w '%{http_code} %{size_download} %header{content-length}'") > 0
    && censusCmd641.indexOf('\\n%') < 0, censusCmd641);
  ok('T-641 transport: the census read carries a write policy rooted at the directory it writes into, and exactly one guarded rm -f of that same generated path follows it (the capFetchPage discipline, not a bare rm)',
    !!(censusSpec641 && censusSpec641.sandboxPolicy && censusSpec641.sandboxPolicy.mode === 'workspace-write'
      && censusSpec641.sandboxPolicy.workspaceRoot === CAPDIR641)
    && rmsCensus641(CTRANS641.bag).filter(function (c) { return c === "rm -f '" + tmpCensus641 + "'"; }).length === 1,
    { policy: censusSpec641 && censusSpec641.sandboxPolicy, tmp: tmpCensus641, rms: rmsCensus641(CTRANS641.bag) });
  ok('T-641 transport: the answer names the bytes it read from disk, so a whole census and a cut one cannot look the same on the page',
    transAns641.ok === true && transAns641.library_state === 'complete' && transAns641.installed_count === 4
    && typeof transAns641.census_bytes === 'number' && transAns641.census_bytes > 1000,
    { bytes: transAns641.census_bytes, installed: transAns641.installed_count });
  CTRANS641.bag.release();

  // A census shorter than the server promised is an interrupted transfer, and the host must say so rather than
  // hand a torso to the parser and answer "3 installed". The fixture promises the Content-Length cpu1.test
  // really answered (85 915) and puts a third of it on disk.
  const CTRUNC641 = makeCtx({ fastTimers: true, audit: true, auditSizesTruncated: true });
  mod.apply(CTRUNC641.ctx);
  await tick(40);
  const apiTrunc641 = CTRUNC641.bag.registered.find(function (x) { return x.path === '/api/deepamp'; }).handler;
  await call(apiTrunc641, '/api/deepamp/get_models?fn=tts', 'GET');
  const truncAns641 = JSON.parse((await call(apiTrunc641, '/api/deepamp/endpoint_library?fn=tts&id=primary', 'GET')).body);
  const truncAns641b = JSON.parse((await call(apiTrunc641, '/api/deepamp/endpoint_library?fn=tts&id=primary', 'GET')).body);
  ok('T-641 transport: a census body shorter than the server promised is reported as a truncation, with byte counts on both sides and no counts presented',
    truncAns641.ok === false && /truncated at \d+ bytes of 85915/.test(String(truncAns641.error))
    && truncAns641.packages_total === undefined && truncAns641.installed_count === undefined
    && truncAns641.library_state === 'unavailable', truncAns641);
  ok('T-641 transport: a truncated census is never cached, and the failure path still removed its temp file (removal is never skipped)',
    truncAns641b.from_cache !== true && truncAns641b.census_bytes === undefined
    && (function () {
      const cmds641 = CTRUNC641.bag.shellCalls.filter(function (c) { return /package-sizes/.test(String(c)); }).map(String);
      if (cmds641.length !== 2) return false;
      const rms641 = rmsCensus641(CTRUNC641.bag);
      return cmds641.every(function (cmd641) {
        const o641 = cmd641.indexOf(" -o '");
        if (o641 < 0) return false;
        const p641 = cmd641.slice(o641 + 5, cmd641.indexOf("' -w '", o641));
        return rms641.filter(function (c641) { return c641 === "rm -f '" + p641 + "'"; }).length === 1;
      });
    })(),
    { reads: CTRUNC641.bag.shellCalls.filter(function (c) { return /package-sizes/.test(String(c)); }).length, rms: rmsCensus641(CTRUNC641.bag) });
  CTRUNC641.bag.release();

  // T-641 item 16: the engine's own `category` seeds the panel grouping; our FAMILY_INFO row stays an OVERRIDE.
  // mira_tts: our row says 'tts', the engine spec says 'audio_generation', the wire task says 'music' — our row wins.
  // newkit_asr: no row here at all, the wire task says 'tts', the engine spec says 'speech_analysis' — the engine wins.
  const CSEED = makeCtx({ fastTimers: true, audit: true });
  mod.apply(CSEED.ctx);
  await tick(40);
  const apiSeed = CSEED.bag.registered.find(function (x) { return x.path === '/api/deepamp'; }).handler;
  await call(apiSeed, '/api/deepamp/get_models?fn=tts', 'GET');
  const seedPip = JSON.parse((await call(apiSeed, '/api/deepamp/get_pipelines', 'GET')).body);
  ok('T-641: a family our table does not know is grouped by what the ENGINE says about it, not by the wire task',
    (seedPip.catalog.speech_analysis || []).some(function (x) { return x.id === 'orphan-tts'; })
    && !(seedPip.catalog.tts || []).some(function (x) { return x.id === 'orphan-tts'; }), seedPip.catalog);
  ok('T-641: a family our table DOES know keeps our word — the table is an override layer, not a fallback',
    (seedPip.catalog.tts || []).some(function (x) { return x.id === 'mira-tts'; })
    && !(seedPip.catalog.audio_generation || []).some(function (x) { return x.id === 'mira-tts'; }), seedPip.catalog);
  CSEED.bag.release();

  r = await call(api, '/api/deepamp/endpoint_library', 'POST');
