  const unloadAllPkg870 = JSON.parse((await call(apiPkg870, '/api/deepamp/unload_all_models', 'POST',
    { fn: 'tts', package_id: 'qwen3_tts_1_7b_base_q8_0' })).body);
  ok('T-870: the two unload verbs refuse the field in words instead of ignoring it — a package id names something to load, and an unload drops what is resident',
    unloadPkg870.ok === false && /is a load field/.test(String(unloadPkg870.error))
    && unloadAllPkg870.ok === false && /is a load field/.test(String(unloadAllPkg870.error))
    && CPKG870.bag.shellCalls.filter(function (c) { return /-X POST '[^']*\/v1\/models\/unload/.test(String(c)); }).length === 0
    // The refusal itself writes a log record that NAMES the verb, so the count is of curl commands, not of any
    // line that mentions the word — that is the difference between "no engine was asked" and "nothing was written".
    && CPKG870.bag.shellCalls.filter(function (c) { return /-X POST '[^']*\/v1\/tasks\/unload_all_models/.test(String(c)); }).length === 0,
    { unload: unloadPkg870.error, all: unloadAllPkg870.error });

  const recs870 = perf870(CPKG870.bag).filter(function (p) { return p.ev === 'queue_op' && p.verb === 'model_load'; });
  ok('T-870: the one record per call the model verbs already write names the path the load took — an empty string is the old shape, and a load that named a package says so on the line',
    recs870.length === 3 && recs870[0].package_id === '' && recs870[1].package_id === 'qwen3_tts_1_7b_base_q8_0'
    && recs870[2].package_id === 'minimax_h3_q4_k' && recs870.every(function (p) { return p.action === 'done'; }),
    { records: recs870.map(function (p) { return { model: p.model, package_id: p.package_id, action: p.action }; }) });

  // T-870b (2026-11-16, measured live on the lane, after the operator's restart). A package-id load aimed at
