  const recs870b = perf870(CPKG870.bag).filter(function (p) { return p.ev === 'queue_op' && p.verb === 'model_load'; });
  ok('T-870b: the record a load aimed at a named endpoint writes names both the package and the endpoint it talked to — a record that named only the model would leave a reader guessing which engine was asked',
    recs870b.length === 4 && recs870b[3].package_id === 'qwen3_tts_1_7b_base_q8_0'
    && recs870b[3].action === 'done' && String(recs870b[3].endpoint_id) === String(otherId870),
    { records: recs870b.map(function (p) { return { model: p.model, package_id: p.package_id, endpoint_id: p.endpoint_id, action: p.action }; }) });

