    const pl762 = JSON.parse((await call(api762(K762), '/api/deepamp/playlist_list', 'GET')).body);
    const ids762 = pl762.items.map(function (i) { return i.id; });
    const want762 = ['ap-0215', 'ap-0214', 'ap-0213', 'ap-0212', 'ap-0211', 'ap-0210', 'ap-0209', 'ap-0208', 'ap-0207', 'ap-0206', 'ap-0205'];
