    const C473 = mk191({});
    await tick(30);
    const q473 = JSON.parse((await call(C473.api, '/api/deepamp/dispatch_speaker_asr', 'POST', {
      file_path: WAV191, diar_model: 'sortformer_diar_f16',
    })).body);
    ok('T-473: a quant variant of a diar family that cannot produce the artifact is refused at dispatch, before a model load',
      q473.ok === false && /sortformer_diar_f16/.test(String(q473.error))
      && /return_frame_probabilities/.test(String(q473.error)), q473.error);
