        version: 3,
        endpoints: {
          tts: { url: (opts.ttsUrl === undefined ? 'http://10.0.0.10:8963' : opts.ttsUrl), route: 'speech' },
          stt: { url: (opts.sttUrl === undefined ? 'http://10.0.0.10:8962' : opts.sttUrl), route: 'speech' },
        },
        counter: 1, playlist: [],
        voices: {
          tomboy1: voice203('tomboy1'), tomboy2: voice203('tomboy2'), tomboy3: voice203('tomboy3'),
          tomboy4: voice203('tomboy4'), tomboy5: voice203('tomboy5'), tomboy6: voice203('tomboy6'),
          ghost_voice: voice203('ghost_voice', false),
        },
        // T-633 RE-POINT (2026-10-23): the batch part-splitting default moved to OFF; the claims in this block are
        // about the PARTS of one scene spreading over endpoints, so this fixture seeds the switch ON.
