      noFile.ok === false && badTask.ok === false && badBatch.ok === false && badKnob.ok === false
      && refused.some(function (p) { return p.verb === 'dispatch_stt' && /file_path/.test(p.why); })
      && refused.some(function (p) { return p.verb === 'dispatch_task' && /task_kind/.test(p.why); })
