    const badPin = await call(R207.api, '/api/deepamp/dispatch_tts', 'POST', { fn: 'tts', model: 'm207', text: 'bad pin', endpoint_id: 'not-an-id' });
    const badRoute = await call(R207.api, '/api/deepamp/no_such_verb_207', 'GET');
