      const seed = { version: 3, endpoints: { tts: { url: PRIM221, route: 'speech' }, stt: { url: 'http://10.0.0.10:8962', route: 'speech' } },
        counter: 99, playlist: [row221(opts.row)].concat(opts.extra || []), voices: {} };   // T-646: opts.extra
