    const takeLines604 = bodies604.reduce(function (acc, b) { return acc.concat(String(b.input || '').split('\n')); }, []);
    const doubled604 = takeLines604.filter(function (l) { return /^\[S\d\] \[S\d\]/.test(l); });
    // One leading marker per line, measured as a COUNT of markers at the FRONT of the line. An earlier draft looked
    // for any `[S` past position 4 and so counted the deliberate mid-sentence marker below as a second one; the pin
