    const badLabel359 = JSON.parse((await call(api359, '/api/deepamp/voice_groups', 'POST', { name: 'voy_janeway', groups: ['Star Trek!!'] })).body);
    const afterBad359 = JSON.parse((await call(api359, '/api/deepamp/voice_registry', 'GET')).body);
