    ok('T-360: the family answer and the checkpoint answer are BOTH reported side by side — the family declares four speakers, lfm2-audio-jp-tts declares none',
      (function () {
        const fam = (cap360.families || {}).lfm2_audio || {};
        const jp = mv360['lfm2-audio-jp-tts'];
        return JSON.stringify(fam.builtin_voices) === '["us_male","us_female","uk_male","uk_female"]'
          && fam.default_voice === 'us_male'
          && !!jp && jp.declared_empty === true && jp.voices.length === 0 && jp.family === 'lfm2_audio';
      })(),
      { family: ((cap360.families || {}).lfm2_audio || {}).builtin_voices, jp: mv360['lfm2-audio-jp-tts'] });
    const rv360 = JSON.parse((await call(api360, '/api/deepamp/refresh_voices?fn=tts&model=lfm2-audio-jp-tts&caps=1', 'GET')).body);
    ok('T-360: refresh_voices honours the MODEL\'s own declaration — the JP checkpoint answers NO built-in voices and says the model said so, instead of inheriting its family\'s four speakers',
      rv360.ok !== false && rv360.builtins.length === 0 && rv360.builtins_source === 'model' && rv360.default_voice === '',
      { builtins: rv360.builtins, builtins_source: rv360.builtins_source, default_voice: rv360.default_voice });
    const rv360p = JSON.parse((await call(api360, '/api/deepamp/refresh_voices?fn=tts&model=pocket_tts_en_q8&caps=1', 'GET')).body);
    ok('T-360: a model the table does NOT speak for still falls through to the family capability answer, unchanged (pocket_tts -> ["alba"], builtins_source "capability")',
      JSON.stringify(rv360p.builtins) === '["alba"]' && rv360p.builtins_source === 'capability' && rv360p.default_voice === 'alba',
      { builtins: rv360p.builtins, builtins_source: rv360p.builtins_source, default_voice: rv360p.default_voice });
    ok('T-360: the model-level read cost nothing extra — the page was fetched once for all of it',
      C360.bag.capabilityCalls.length === 1 && /^curl /.test(String(C360.bag.capabilityCalls[0])),
      C360.bag.capabilityCalls.slice(0, 2));
