  // --- T-519 (user 2026-10-16, verbatim): "the top row of the log section should show the version number on the
  //     right side of the deepamp plugin, taken from SSOT value (not hardcoded)") ---------------------------------
  // The host answers the version because the host is the half that CAN read the manifest. The browser half is
  // loaded as inline text (window.__DSH_BOOT__) with a require() that resolves registered client modules only,
  // so it has no file access and no exports map — measured, not assumed. The test then proves the answer IS the
  // manifest by reading package.json itself and comparing, which is the difference between an SSOT and a string
  // that happens to match.
  console.log('\n--- T-519: GET plugin_version — the manifest answers, the answer names where it came from, and neither face types a version ---');
  {
    const fsx519 = require('fs');
    const MAN519 = path.join(path.dirname(LIB), '..', 'package.json');
    const realManifest519 = JSON.parse(fsx519.readFileSync(MAN519, 'utf8'));
    const L519 = makeCtx();
    mod.apply(L519.ctx);
    const api519 = L519.bag.registered.find(function (r519) { return r519.path === '/api/deepamp'; }).handler;
    await tick(40);
    const J519 = function (r519) { return JSON.parse(r519.body); };
    const v1 = J519(await call(api519, '/api/deepamp/plugin_version', 'GET'));
    ok('T-519: the host answers the version, and the value IS the manifest — read independently by the test and compared, so this is the SSOT and not a string that happens to match',
      v1.ok === true && v1.version === realManifest519.version && v1.name === realManifest519.name,
      { answered: v1.version, manifest: realManifest519.version, name: v1.name });
    ok('T-519: the answer names its own source and the door it came through, so the panel can say where the number came from instead of implying it',
      typeof v1.source === 'string' && /(^|\/)package\.json$/.test(v1.source)
      && ['module import', 'ctx fs read'].indexOf(v1.via) >= 0 && isFinite(Number(v1.read_at)),
      { source: v1.source, via: v1.via });
    const v2 = J519(await call(api519, '/api/deepamp/plugin_version', 'GET'));
    ok('T-519: a successful read is kept — a manifest does not change under a running host, so a second ask answers the SAME read rather than parsing the file again',
      v2.ok === true && v2.read_at === v1.read_at, { first: v1.read_at, second: v2.read_at });
    const post519 = await call(api519, '/api/deepamp/plugin_version', 'POST', {});
    ok('T-519: it is a read route — POST is refused, and the refusal is the plugin\'s own named method refusal',
      post519.code === 405 && post519.body.indexOf('method not allowed') >= 0,
      { code: post519.code, body: String(post519.body).slice(0, 60) });
    ok('T-519 source: NEITHER face types a version. No semver-shaped quoted string exists in lib/index.js or lib/client.js, and the manifest path is derived from the host module\'s own URL rather than written out',
      (function () {
        const srcH519 = fsx519.readFileSync(LIB, 'utf8');
        const srcC519 = fsx519.readFileSync(path.join(path.dirname(LIB), 'client.js'), 'utf8');
        const semver = /['"]\d+\.\d+\.\d+['"]/;
        return !semver.test(srcH519) && !semver.test(srcC519)
          && /new URL\('\.\.\/package\.json', import\.meta\.url\)/.test(srcH519)
          && /import\('\.\.\/package\.json', \{ with: \{ type: ['"]json['"] \} \}\)/.test(srcH519)
          && srcC519.indexOf("call('plugin_version'") > 0;
      })(), { quoted_versions_in_either_face: 0 });
    ok('T-519 source: a FAILED read is deliberately NOT cached — a host that could not read its manifest once may read it on the next ask, and the panel must not be frozen on the first failure',
      (function () {
        const srcH519 = fsx519.readFileSync(LIB, 'utf8');
        return /if \(ans519\.ok\) pluginVersionCache519 = ans519;/.test(srcH519);
      })(), { caches_only_success: true });
    L519.bag.release();
  }

