      const seedFiles468 = JSON.parse(JSON.stringify(files468));
      const L468 = makeCtx(Object.assign({ convert468: true, fastTimers: true, fsSeed: Object.assign(seedFiles468, { [STATE]: JSON.stringify(seed468b) }) }, o468 || {}));
      mod.apply(L468.ctx);
      const api468 = L468.bag.registered.find(function (r468) { return r468.path === '/api/deepamp'; }).handler;
      const audio468 = L468.bag.registered.find(function (r468) { return r468.path === '/deepamp'; }).handler;
