    // leaf and saved as the informative name. ap-1004 is stored under a 109-character stem so the limit is measured.
    const rowLong468 = (rows468.items || []).find(function (r468) { return r468.id === 'ap-1004'; }) || {};
    const stemLong468 = String(LONG468).split('/').pop().replace(/\.[^.]*$/, '');
