    const legsBeforeTxt468 = m468.L.bag.shellCalls.filter(function (c468) { return /^ffmpeg/.test(String(c468)); }).length;
    const txtConv468 = J468(await call(m468.api, '/api/deepamp/convert_item', 'POST', { id: 'ap-1003', format: 'ogg' }));
    const legsAfterTxt468 = m468.L.bag.shellCalls.filter(function (c468) { return /^ffmpeg/.test(String(c468)); }).length;
    ok('T-468 (T-897: the pinned absolute count became a before/after difference): a transcript row is refused too, by name, and pays no shell leg of its own',
      txtConv468.ok === false && /transcript, not audio/.test(txtConv468.error) && legsAfterTxt468 === legsBeforeTxt468,
      { error: String(txtConv468.error).slice(0, 100), legs_before: legsBeforeTxt468, legs_after: legsAfterTxt468 });
    const noRow468 = J468(await call(m468.api, '/api/deepamp/convert_item', 'POST', { id: 'ap-9999', format: 'ogg' }));
