    await tick(400);
    const c2row = await row649(C6.api, c2.job_id);
    ok('T-649 (e): while the cooldown hold is live the next row is placed on the other lane',
      c2row.status === 'ok' && c2row.endpoint_id === cAdd.endpoint.id
        && speech649(C6.bag, 'http://cpu2.test:8963').length === 1,
      { status: c2row.status, endpoint_id: c2row.endpoint_id, cpu2_calls: speech649(C6.bag, 'http://cpu2.test:8963').length });
    // (f) the re-arm. The brake lives in state.json; the record that makes a parked row re-check
    // it (autoPauseInfo) is session-local. Before T-649 a plugin hold that survived a harness
    // restart had NO re-check at all - only a hand press could lift it. A seeded plugin hold must
    // fire the bounded probe; a seeded OPERATOR hold must not (ruling 2026-10-26: never an
    // operator hold).
    const seed649 = function (heldBy) {
      return JSON.stringify({
        version: 3,
        endpoints: { tts: { url: 'http://10.0.0.10:8963', route: 'speech' }, stt: { url: 'http://10.0.0.10:8962', route: 'speech' } },
        counter: 1,
        playlist: [{ id: 'ap-0649', fn: 'tts', kind: 'tts', status: 'queued', text: 'restored behind the restored hold',
          model: 'm649', created: 1, endpoint_id: 'primary', endpoint_url: 'http://10.0.0.10:8963' }],
        voices: {},
        primary_flags: { tts: { enabled: false, batch_allowed: true, held_by: heldBy, held_at: Date.now(), hold_reason: 'engine reports its own model slot is wedged - seeded' } },
      });
    };
    const mk649Seed = function (heldBy) {
      const m = makeCtx({ fastTimers: true, healthOk: true, modelsPayload: MODELS649, fsSeed: { [STATE]: seed649(heldBy) } });
      mod.apply(m.ctx);
      return { bag: m.bag, api: m.bag.registered.find(function (x) { return x.path === '/api/deepamp'; }).handler };
    };
