    // voice_samples (so it IS a samples_only family), kokoro_tts declares builtin voices and no voice_samples.
    const PAGE657 = 'var kx={'
      + 'moss_ttsd:[{name:"instruct",type:"text",label:"Delivery instruction",default:""},'
      + '{name:"temperature",type:"number",label:"Temperature",default:1.5,minimum:0,step:.1}],'
      + 'kokoro_tts:[{name:"temperature",type:"number",default:1}],'
      + 'pocket_tts:[{name:"temperature",type:"number",default:1}]};'
      + 'var q657={schema_version:1,family:"moss_ttsd",tasks:["tts"],ui:{builtin_voices:[],default_voice:""},'
      + 'options:{request:[{name:"voice_samples",type:"string",description:"positional cast paths"},'
      + '{name:"reference_text",type:"string"},{name:"language",type:"string"},{name:"instruct",type:"string"}]}};'
      + 'var k657={schema_version:1,family:"kokoro_tts",tasks:["tts"],ui:{builtin_voices:["af_heart"],default_voice:"af_heart"}};';
    // The primary engine's own /v1/models answer: it names moss_ttsd and kokoro_tts. `moss_ttsd_q4_k` is NOT in
