    mod.apply(E663.ctx);
    const apiE663 = E663.bag.registered.find(function (r) { return r.path === '/api/deepamp'; }).handler;
    const e663 = JSON.parse((await call(apiE663, '/api/deepamp/dispatch_stt', 'POST',
      { fn: 'stt', model: 'sortformer_diar', file_path: `${SUITE_STORE}/stt/uploads/scene.wav` })).body);
    await tick(400);
    const eRow663 = e663.job_id ? JSON.parse((await call(apiE663, '/api/deepamp/job_status/' + e663.job_id, 'GET')).body) : {};
    const eDiarRun663 = E663.bag.specs.filter(function (s) {
      return /\/v1\/tasks\/run/.test(s.command) && /sortformer_diar/.test(String(s.stdin || ''));
    });
    ok('T-663 (e): a plain diarisation press that names sortformer_diar still runs sortformer_diar — the default is a fallback, not a hijack of the diar lane',
      e663.ok === true && eDiarRun663.length >= 1 && !eRow663.speaker_asr,
      { ok: e663.ok, error: e663.error, diar_runs: eDiarRun663.length, has_sasr_block: !!eRow663.speaker_asr });

    // (f) the source contract: the default lives in ONE named place, no diar-default literal survived, and the
    // marker is written once on the record and once on the row view.
    // (T-880 re-expression, 2026-11-16, at the operator's batch word: the fallbacks now run through the family
    // resolver — one declaration carrying the current engine id as its last-resort value, five resolver mentions
