  await svc715.call('pause_fn', { method: 'POST', body: { fn: 'tts' } });
  feed715 = await feedOf715(0);
  ok('T-715 i5: the same verb from the panel side records nothing — the panel knows what its own button did',
    feed715.json.activity.length === 1, feed715.json.activity.length);

