  // A body-level refusal in this plugin answers 200 with ok:false and the reason (the established
  // convention every other suite here already holds). What the service must not do is turn that into a
  // transport story — a model needs the reason the lane gave, because that is what it acts on. Whether
  // 200 is the right status for a refusal is a separate question, pre-existing and not changed here.
  const noBody715 = await svc715.call('save_voice', { method: 'POST', body: {}, via: 'agent' });
  ok('T-715 i7: a body the lane refuses reaches the caller as the reason the lane gave, not as a transport failure',
    noBody715.json.ok === false && /voice name required/.test(String(noBody715.json.error))
    && noBody715.json.error === noBody715.json.error && noBody715.status === 200,
    { status: noBody715.status, error: noBody715.json.error });

  const askPlay715 = svc715.ask('play', { job_id: 'ap-77' });
