  ok('T-715 i16: the feed is host memory, not state — nothing about it reaches the persisted store',
    !JSON.stringify(L715.bag.fsMap || {}).includes('lane_activity')
    && !Object.keys(L715.bag.fsMap || {}).some(function (k) { return /activity/.test(k); }),
    Object.keys(L715.bag.fsMap || {}).filter(function (k) { return /activity/i.test(k); }));

  // ---- T-800 (2026-11-12): the panel's auto-generation chain, reported and answered ------------------------
  // The operator's ask was that the agent be told the chain state during playlist and job reads and be able to
  const agRead716 = async function (verb716, method716, body716) {
    const r716 = await call(lApi715, '/api/deepamp/' + verb716, method716 || 'GET', body716);
    let j716 = null;
    try { j716 = JSON.parse(r716.body); } catch (e716) { j716 = null; }
    return { code: r716.code, json: j716 || {} };
  };

  // arm it, and the shape chosen for it was, in the operator's words, "Report only, no host record": the panel
  // reports its own chain, this plugin holds that report in memory, nothing of it is persisted, and when nobody
  // is reporting the answer says it does not know instead of reading a silence as a switch being off.
  const agBefore716 = await agRead716('queue_status', 'GET');
  ok('T-800: before any panel reports, the answer says it does not know - a closed panel and a chain that is off look identical from this side, and the answer does not guess',
    agBefore716.code === 200 && !!agBefore716.json.auto_gen && agBefore716.json.auto_gen.state === 'unknown'
    && /no panel report/.test(agBefore716.json.auto_gen.note) && Array.isArray(agBefore716.json.auto_gen.started_rows)
    && agBefore716.json.auto_gen.started_rows.length === 0, { auto_gen: agBefore716.json.auto_gen });
  const agGet716 = await agRead716('auto_gen_state', 'GET');
  ok('T-800: the report is a write verb - a GET on it is answered the way every other read verb here is answered',
    agGet716.code === 405, agGet716.code);
  const agPost716 = await agRead716('auto_gen_state', 'POST', { armed: true, ahead: '2', started: ['ap-9001', 'ap-9002'], reason: 'armed from the panel' });
  const agStatus716 = await agRead716('queue_status', 'GET');
  ok('T-800: a reported chain is answered beside the queue read the agent already makes - armed, the count it keeps ahead, the rows it started, and who the claim came from',
    agPost716.code === 200 && agPost716.json.ok === true && agPost716.json.recorded === true
    && agStatus716.json.auto_gen.state === 'armed' && agStatus716.json.auto_gen.ahead === '2'
    && agStatus716.json.auto_gen.started_rows.indexOf('ap-9001') >= 0 && agStatus716.json.auto_gen.started_count === 2
    && agStatus716.json.auto_gen.source === 'panel' && typeof agStatus716.json.auto_gen.reported_ms_ago === 'number',
    agStatus716.json.auto_gen);
  const agDispatch716 = await agRead716('dispatch_tts', 'POST', { fn: 'tts', model: 'qwen3-tts', text: 'the row a chain is going to be claimed for', voice: 'tomboy1' });
  const agRowId716 = String((agDispatch716.json || {}).route_url || '').split('/').pop();
  const agClaim716 = await agRead716('auto_gen_state', 'POST', { armed: true, ahead: '1', started: [agRowId716], reason: 'the chain took this row' });
  const agJob716 = await agRead716('job_status/' + encodeURIComponent(agRowId716), 'GET');
  const agPl2716 = await agRead716('playlist_list', 'GET');
  const agMarked716 = (agPl2716.json.items || []).filter(function (r716) { return r716.auto_started === true; }).map(function (r716) { return r716.id; });
  ok('T-800: a row the live report names is marked in the single-row read and in the playlist read alike - the mark is computed at the read from what the panel named, and nothing of it is stored on the row',
    agDispatch716.json.ok === true && !!agRowId716 && agClaim716.json.recorded === true
    && agJob716.json.auto_started === true && agMarked716.indexOf(agRowId716) >= 0
    && agPl2716.json.auto_gen.started_rows.indexOf(agRowId716) >= 0,
    { row: agRowId716, marked: agMarked716, dispatch: agDispatch716.json });
  const agClear716 = await agRead716('auto_gen_state', 'POST', { armed: false, started: [], reason: 'the chain was disengaged' });
  const agJob2716 = await agRead716('job_status/' + encodeURIComponent(agRowId716), 'GET');
  const agPl3716 = await agRead716('playlist_list', 'GET');
  ok('T-800: the same row is not marked once the report no longer names it - an old claim about a chain nobody is running is not a fact about a row, and the key is absent rather than false',
    agClear716.json.recorded === true && agJob2716.json.auto_started === undefined
    && (agPl3716.json.items || []).every(function (r716) { return r716.auto_started === undefined; }),
    { row: agRowId716, still_marked: (agPl3716.json.items || []).filter(function (r716) { return r716.auto_started === true; }).map(function (r716) { return r716.id; }) });
  const agNoMode716 = svc715.ask('auto_gen');
  const agFeed716 = await feedOf715(0);
  ok('T-800: arming the chain through the panel needs a mode, and a request without one is refused and records nothing',
    agNoMode716.ok === false && /needs mode/.test(String(agNoMode716.error))
    && !agFeed716.json.activity.some(function (r716) { return r716.action === 'auto_gen'; }), agNoMode716);
  const agOn716 = svc715.ask('auto_gen', { mode: 'on' });
  const agFeed2716 = await feedOf715(0);
  const agRow716 = agFeed2716.json.activity.filter(function (r716) { return r716.action === 'auto_gen'; }).pop() || {};
  ok('T-800: with a mode it is held for the panel in the same channel as play, stop and clear, and the mode travels with it - this plugin runs no chain of its own and says so',
    agOn716.ok === true && agOn716.held === true && agRow716.kind === 'do' && agRow716.mode === 'on'
    && /held for the panel/.test(String(agOn716.note)), { entry: agRow716, answer: agOn716 });
  const agOff716 = await agRead716('auto_gen_state', 'POST', { armed: false, started: [], reason: 'stopped: a job this chain started (ap-9001) was cancelled' });
  const agStatus2716 = await agRead716('queue_status', 'GET');
