    // (k) BOTH DOORS STAND WHERE THE RULE SAYS. The bar-s half is inside the bar; the tasks-lane half is
    //     before the id is spent, and only on the kind this card measured. These are the placement claims
    //     the design rests on, so they are read off the file.
    const gateSrc777 = SRC777.slice(SRC777.indexOf('function capGateVerdict(info, fam, want, modelRecord) {'), SRC777.indexOf('  // Names only line up after normalising'));
    const capGateSrc777 = SRC777.slice(SRC777.indexOf('function capabilityGate(fn, verb, body, endpoint) {'), SRC777.indexOf('  // One place turns a verdict into what the dispatch sees'));
    const taskGateStart777 = SRC777.indexOf("requiredOptionRefusal777('tts', placed.endpoint, fam777, body)");
