    const LYRIC885 = '[verse]\nI keep a barn of borrowed voices,\neach one a wave the shelf has kept, a captain\'s line '
      + 'nobody finished\nwaits in a queue while the engine slept.\n\n[chorus]\nRun the little engine, run it, '
      + 'whip the llama, let it sing.\n';

    await tick(30);
    await call(api885, '/api/deepamp/get_models?fn=tts', 'GET');
    const caps885 = await J885('/api/deepamp/model_capabilities?fn=tts', 'GET');
    const lyrRec885 = (((caps885.families || {}).minimax_music3 || {}).request_options || [])
      .filter(function (p) { return p && p.name === 'lyrics'; })[0] || {};

