    const boundFn885 = (boundStart885 > 0 && boundEnd885 > boundStart885)
      ? new Function('OPTION_LONG_TEXT_MAX', 'return (' + SRC885.slice(boundStart885, boundEnd885) + ');')(4000) : null;
