    const msgNum885 = p885({ takes: { name: 'takes', type: 'int', required: true, min: 1, max: 16 } }, withVal885(new Array(4002).join('a'))).block;
    const msgUnknown885 = p885({ lyrics: { name: 'lyrics', required: true } }, withVal885('x'.repeat(130))).block;
    const msgNone885 = p885({ lyrics: { name: 'lyrics', type: 'string', required: true } },
      Object.assign({}, base885, { options: {}, dropped: ['lyrics'] })).block;
    ok('T-885 (e): the bar-s own message states the rule that applies to the parameter in front of it — free text up to this lane-s ceiling, free text up to the maximum the record states, a number between the bounds the record states — and keeps the old sentence where no type is known, and the missing-name half of the message is untouched',
      /free text, up to 4000 characters, line breaks allowed/.test(msgText885)
      && /free text, up to 200 characters/.test(msgBounded885)
      && /a number \(not below 1, not above 16\)/.test(msgNum885)
      && /short single-line text \(up to 120 characters/.test(msgUnknown885)
      && /This request carries none\./.test(msgNone885)
      && pureStart885 > 0 && pureEnd885 > pureStart885,
      { text: msgText885.slice(0, 240), bounded: msgBounded885.slice(0, 120), num: msgNum885.slice(0, 120), unknown: msgUnknown885.slice(0, 120), none: msgNone885.slice(0, 120) });
    // (f) force:true still steps over the bar, and the row then says what it carried and what it could not.
    //     The value rule is not a bar — the cleaner decides it — so what force buys here is a row that exists
